WITH FilteredTransactions AS (SELECT * FROM transactions WHERE is_flagged = TRUE), summary AS (SELECT is_flagged, QUARTER(txn_time) txn_quarter, COUNT(CASE WHEN merchant = 'Lazada' THEN 1 END) lazada_count, SUM(CASE WHEN txn_type = 'DEBIT' THEN 1 ELSE 0 END) debit_count FROM FilteredTransactions GROUP BY is_flagged, QUARTER(txn_time)) SELECT is_flagged, txn_quarter, debit_count FROM summary;
